import sys

def main():
    data = list(map(int, sys.stdin.read().split()))

    if not data:
        print(0)
        return

    M = data[0]
    N = data[1]

    if M == 0 or N == 0:
        print(0)
        return

    matrix_elements = data[2:2 + M * N]

    matrix = []
    for i in range(M):
        row = []
        for j in range(N):
            row.append(matrix_elements[i * N + j])
        matrix.append(row)

    total_sum = 0
    for i in range(M):
        for j in range(N):
            total_sum += matrix[i][j]

    print(total_sum)

if __name__ == "__main__":
    main()
